$(function () {
  // Fungsi untuk mengatur tipe sidebar berdasarkan lebar jendela
  var setsidebartype = function () {
    var width = window.innerWidth > 0 ? window.innerWidth : screen.width;
    if (width < 1199) {
      $("#main-wrapper").attr("data-sidebartype", "mini-sidebar");
      $("#main-wrapper").addClass("mini-sidebar");
    } else {
      $("#main-wrapper").attr("data-sidebartype", "full");
      $("#main-wrapper").removeClass("mini-sidebar");
      $("#main-wrapper").removeClass("show-sidebar");
    }
  };

  $(window).ready(setsidebartype);
  $(window).on("resize", setsidebartype);

  $(".sidebartoggler").on("click", function () {
    var $mainWrapper = $("#main-wrapper");
    var sidebarType = $mainWrapper.attr("data-sidebartype");

    if (sidebarType === "mini-sidebar") {
      $mainWrapper.toggleClass("show-sidebar");
      $("#main-wrapper").removeClass("mini-sidebar");
      $("#main-wrapper").attr("data-sidebartype", "full");
    } else {
      $mainWrapper.toggleClass("mini-sidebar");
      $("#main-wrapper").attr("data-sidebartype", "mini-sidebar");
      $("#main-wrapper").removeClass("show-sidebar");
    }
  });
});

// Tabel List Tamu
$(document).ready(function () {
  var table = $("#tabel_list_undangan").DataTable({
    processing: true,
    serverSide: false,
    ajax: {
      url: "/invitation/listundangan",
      dataSrc: "data",
    },
    columns: [
      {
        data: null,
        render: function (data, type, row, meta) {
          return meta.row + 1;
        },
      },
      { data: "nama" },
      { data: "partner" },
      { data: "dari" },
      { data: "status" },
        {
            data: "link",
            render: function (data, type, row) {
                const namaTamu = row.partner ? `${row.nama} & ${row.partner}` : row.nama;
                const template = `
Assalamu'alaikum Wr. Wb
Bismillahirahmanirrahim.

Maha suci Allah yang telah menjadikan segala sesuatu lebih indah dan sempurna

Kepada Yth. ${namaTamu}

Tanpa mengurangi rasa hormat, perkenankan kami mengundang Bapak/Ibu/Saudara/i, teman sekaligus sahabat, untuk menghadiri acara pernikahan kami, Gita & Qisthi.

Informasi mengenai detail acara, lokasi, dan waktu lebih lengkap dapat diakses pada tautan terlampir:

${data}

Merupakan suatu kebahagiaan bagi kami apabila Bapak/Ibu/Saudara/i berkenan untuk hadir dan memberikan doa restu.

Mohon maaf perihal undangan hanya dibagikan melalui pesan ini. Terima kasih banyak atas perhatiannya.

Wassalamu'alaikum Wr. Wb.

Kami yang berbahagia
Gita & Qisthi
    `.trim();

                return `
      <div class="d-flex flex-column gap-1">
        <a href="${data}" target="_blank">${data}</a>
        <button class="btn btn-sm btn-success copy-btn" data-message="${template.replace(/"/g, '&quot;')}">
          📋 Salin Undangan
        </button>
      </div>
    `;
            },
        },
      {
        data: "qrcode",
        render: function (data, type, row) {
          return `<img src="/qrcode/${data}" width="80" />`;
        },
      },
      { data: "id", visible: false },
    ],
    order: [[6, "desc"]],
  });

  table.on("order.dt search.dt draw.dt", function () {
    let info = table.page.info();
    table
      .column(0, { search: "applied", order: "applied" })
      .nodes()
      .each(function (cell, i) {
        cell.innerHTML = i + 1 + info.start;
      });
  });
});

// Tabel Daftar Hadir
