$(document).on("click", ".copy-btn", function () {
    const message = $(this).data("message");

    navigator.clipboard.writeText(message).then(() => {
        alert("Teks undangan berhasil disalin ke clipboard!");
    }).catch(err => {
        alert("Gagal menyalin teks.");
        console.error(err);
    });
});

// Input undangan
$("#submit").css("cursor", "pointer");

$(document).on("click", "#submit", function (event) {
  event.preventDefault();

  var csrfName = $("#csrf_token").attr("name");
  var csrfHash = $("#csrf_token").val();
  var nama = $("#nama").val();
  var partner = $("#partner").val();
  // var gender = $("#gender").val();
  var dari = $("#dari").val();
  var status = $("#status").val();

  $.ajax({
    type: "POST",
    url: "/invitation/simpan",
    data: {
      nama: nama,
      partner: partner,
      // gender: gender,
      dari: dari,
      status: status,
      [csrfName]: csrfHash,
    },
    success: function (data) {
      if (data === "error") {
        inputGagal();
      } else {
        $("#nama").val("");
        $("#partner").val("");
        $("#dari").val("");
        $("#gender").val("Pilih");
        $("#status").val("Pilih");

        $("#tabel_list_undangan").DataTable().ajax.reload(null, false);
        inputOk();
      }
    },
  });
});

function inputOk() {
  const Toast = Swal.mixin({
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 3000,
    timerProgressBar: true,
    didOpen: (toast) => {
      toast.addEventListener("mouseenter", Swal.stopTimer);
      toast.addEventListener("mouseleave", Swal.resumeTimer);
    },
  });

  Toast.fire({
    icon: "success",
    title: "Berhasil Menyimpan data undangan!!",
  });
}

function inputGagal() {
  const Toast = Swal.mixin({
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 3000,
    timerProgressBar: true,
    didOpen: (toast) => {
      toast.addEventListener("mouseenter", Swal.stopTimer);
      toast.addEventListener("mouseleave", Swal.resumeTimer);
    },
  });

  Toast.fire({
    icon: "error",
    title: "Gagal menyimpan data undangan!!",
  });
}

function waktuRelatif(datetime) {
  const waktu = new Date(datetime);
  const sekarang = new Date();

  const diffMs = sekarang - waktu;
  const diffSeconds = Math.floor(diffMs / 1000);
  const diffMinutes = Math.floor(diffSeconds / 60);
  const diffHours = Math.floor(diffMinutes / 60);
  const diffDays = Math.floor(diffHours / 24);
  const diffMonths = Math.floor(diffDays / 30);
  const diffYears = Math.floor(diffDays / 365);

  if (diffYears > 0) {
    return `${diffYears} tahun`;
  } else if (diffMonths > 0) {
    return `${diffMonths} bulan`;
  } else if (diffDays > 0) {
    return `${diffDays} hari`;
  } else if (diffHours > 0) {
    return `${diffHours} jam`;
  } else if (diffMinutes > 0) {
    return `${diffMinutes} menit`;
  } else {
    return "Baru saja";
  }
}

let lastUcapanId = 0;
let isFirstLoad = true;

function loadUcapan() {
  $.getJSON("/ucapan/list", function (data) {
    if (!data.length) return;

    const latest = data[0];
    const latestId = parseInt(latest.id_ucapan);

    if (!isFirstLoad && latestId > lastUcapanId) {
      ucapanBaru(latest.pengirim, latest.ucapan);
    }

    lastUcapanId = latestId;
    isFirstLoad = false;
    let html = "";
    data.forEach((chat) => {
      const waktu = waktuRelatif(chat.time_created);
      html += `
        <li>
          <a href="javascript:void(0)" class="px-3 py-2 bg-hover-light-black d-flex align-items-start justify-content-between chat-user" id="chat_user_${chat.id}" data-user-id="${chat.id}">
            <div class="d-flex align-items-center">
              <span class="position-relative">
                <img src="/images/profile/profile.png" alt="${chat.nama}" width="36" height="36" class="rounded-circle" />
                <span class="position-absolute bottom-0 end-0 p-1 badge rounded-pill bg-${chat.dari}">
                  <span class="visually-hidden">Status</span>
                </span>
              </span>
              <div class="ms-2 d-inline-block w-75">
                <h1 class="mb-1 fw-semibold chat-title" style="font-size: 9pt;" data-username="${chat.pengirim}">
                  ${chat.pengirim}
                </h1>
                <span class="fs-2 text-body-color d-block text-wrap text-justify">${chat.ucapan}</span>
              </div>
            </div>
            <p class="fs-1 mb-0 text-muted text-nowrap">${waktu}</p>
          </a>
        </li>
      `;
    });

    $("#chat-list").html(html);
  });
}

function ucapanBaru(nama, ucapan) {
  Swal.fire({
    title: `${nama} mengucapkan:`,
    text: ucapan,
    icon: "success",
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 3000,
    timerProgressBar: true,
  });
}

loadUcapan();
setInterval(loadUcapan, 5000);

// Scan barcode
document.addEventListener("DOMContentLoaded", function () {
    const inputScanQR = document.getElementById("scanQR");

    inputScanQR.addEventListener("keydown", function (e) {
        if (e.key === "Enter") {
            e.preventDefault();

            const kodeQR = inputScanQR.value.trim();
            if (kodeQR === "") return;

            fetch("/invitation/get-tamu", {
                method: "POST",
                headers: {
                    "Content-Type": "application/x-www-form-urlencoded",
                },
                body: `uniqid=${encodeURIComponent(kodeQR)}`,
            })
                .then((response) => response.json())
                .then((result) => {
                    if (result.status) {
                        const data = result.data;

                        const namaLengkap = data.partner
                            ? `${data.nama} & ${data.partner}`
                            : data.nama;

                        const jumlahKonf = data.nama && data.partner ? 2 : 1;

                        Swal.fire({
                            title: "Selamat datang",
                            html: `
                <p><strong>${namaLengkap} - ${data.dari}</strong></p>
                <p><strong>Konfirmasi</strong></p>
                <input id="namaTamu" type="text" class="swal2-input" value="${data.nama}" placeholder="Nama Tamu"/>
                <input id="partnerTamu" type="text" class="swal2-input" value="${data.partner || ''}" placeholder="Partner (jika ada)"/>
                <label for="jumlahHadir">Jumlah Hadir:</label>
                <input id="jumlahHadir" type="number" class="swal2-input" value="${jumlahKonf}" placeholder="Isi jumlah yang hadir" min="1"/>
              `,
                            imageUrl: "/images/logos/tittleLogo.png",
                            imageWidth: 100,
                            imageHeight: 100,
                            showCancelButton: true,
                            confirmButtonText: "Konfirmasi",
                            preConfirm: () => {
                                const jumlahHadir = document.getElementById("jumlahHadir").value;
                                const nama = document.getElementById("namaTamu").value.trim();
                                const partner = document.getElementById("partnerTamu").value.trim();

                                if (!jumlahHadir || parseInt(jumlahHadir) < 1) {
                                    Swal.showValidationMessage("Jumlah hadir harus minimal 1");
                                    return false;
                                }

                                if (nama === "") {
                                    Swal.showValidationMessage("Nama tidak boleh kosong");
                                    return false;
                                }

                                return { jumlah: jumlahHadir, nama, partner };
                            },
                        }).then((swalResult) => {
                            if (swalResult.isConfirmed) {
                                const { jumlah, nama, partner } = swalResult.value;
                                const idInvitation = data.id;

                                fetch("/invitation/simpan-kehadiran", {
                                    method: "POST",
                                    headers: {
                                        "Content-Type": "application/x-www-form-urlencoded",
                                    },
                                    body: `id_invitation=${encodeURIComponent(
                                        idInvitation
                                    )}&jumlah=${encodeURIComponent(
                                        jumlah
                                    )}&nama=${encodeURIComponent(
                                        nama
                                    )}&partner=${encodeURIComponent(partner)}`,
                                })
                                    .then((res) => res.json())
                                    .then((res) => {
                                        if (res.status) {
                                            Swal.fire({
                                                title: "Tersimpan!",
                                                text: res.message || "Kehadiran terkonfirmasi.",
                                                icon: "success",
                                                showConfirmButton: false,
                                                timer: 3000,
                                                timerProgressBar: true,
                                            }).then(() => {
                                                if ($("#tabel_daftar_hadir").length) {
                                                    $("#tabel_daftar_hadir").DataTable().ajax.reload(null, false);
                                                }
                                            });
                                        } else {
                                            Swal.fire("Gagal", res.message || "Gagal menyimpan data.", "error");
                                        }
                                    })
                                    .catch((err) => {
                                        console.error("❌ Gagal menyimpan:", err);
                                        Swal.fire("Error", "Terjadi kesalahan saat menyimpan.", "error");
                                    });
                            }
                        });
                    } else {
                        Swal.fire({
                            title: "Tamu tidak ditemukan",
                            text: result.message,
                            icon: "error",
                        });
                    }

                    inputScanQR.value = "";
                })
                .catch((err) => {
                    console.error("❌ Gagal ambil data:", err);
                    Swal.fire({
                        title: "Terjadi Kesalahan",
                        text: "Gagal memproses permintaan.",
                        icon: "error",
                    });
                });
        }
    });
});


document.addEventListener("DOMContentLoaded", function () {
  const importBtn = document.getElementById("btn-import");

  importBtn.addEventListener("click", function (e) {
    e.preventDefault();

    Swal.fire({
      title: "Import Undangan Excel",
      html: `
        <input type="file" id="excelFile" class="swal2-file" accept=".xlsx,.xls" />
      `,
      showCancelButton: true,
      confirmButtonText: "Upload",
      cancelButtonText: "Batal",
      preConfirm: () => {
        const fileInput = document.getElementById("excelFile");
        const file = fileInput.files[0];

        if (!file) {
          Swal.showValidationMessage("Pilih file Excel terlebih dahulu.");
        }

        return file;
      },
    }).then((result) => {
      if (result.isConfirmed) {
        const formData = new FormData();
        formData.append("file_excel", result.value);

        fetch("/invitation/import-undangan", {
          method: "POST",
          body: formData,
        })
          .then((res) => res.json())
          .then((data) => {
            if (data.status) {
              Swal.fire(
                "Berhasil!",
                data.message || "File berhasil diimport.",
                "success"
              ).then(() => {
                // reload datatable kalau perlu
                if (window.$ && $.fn.DataTable) {
                  $("#tabel_list_undangan")
                    .DataTable()
                    .ajax.reload(null, false);
                }
              });
            } else {
              Swal.fire(
                "Gagal",
                data.message || "Gagal mengimpor file.",
                "error"
              );
            }
          })
          .catch((err) => {
            console.error("❌ Upload error:", err);
            Swal.fire("Error", "Terjadi kesalahan saat mengunggah.", "error");
          });
      }
    });
  });
});




const scanner = new Html5Qrcode("reader");

Html5Qrcode.getCameras().then((devices) => {
  if (devices.length > 0) {
    const cameraId = devices[0].id;

    scanner.start(cameraId, { fps: 10, qrbox: 250 }, async (kodeQR) => {
      scanner.pause();

      try {
        const response = await fetch("/invitation/get-tamu", {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: `uniqid=${encodeURIComponent(kodeQR)}`,
        });

        const result = await response.json();

        if (result.status) {
          const data = result.data;

          Swal.fire({
            title: "Selamat Datang",
            html: `
              <p><strong>${data.nama} & ${data.partner}</strong></p>
              <p>Dari: ${data.dari}</p>
              <input id="namaTamu" type="text" class="swal2-input" value="${data.nama}" />
              <input id="partnerTamu" type="text" class="swal2-input" value="${data.partner}" />
              <input id="jumlahHadir" type="number" class="swal2-input" placeholder="Jumlah Hadir" min="1" />
            `,
            imageUrl: "/images/logos/tittleLogo.png",
            imageWidth: 100,
            imageHeight: 100,
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: "Konfirmasi",
            didOpen: () => {
              setTimeout(
                () => document.getElementById("jumlahHadir").focus(),
                50
              );
            },
            preConfirm: () => {
              const jumlah = document.getElementById("jumlahHadir").value;
              const nama = document.getElementById("namaTamu").value.trim();
              const partner = document
                .getElementById("partnerTamu")
                .value.trim();

              if (!jumlah || parseInt(jumlah) < 1) {
                Swal.showValidationMessage("Jumlah hadir minimal 1");
              }
              if (nama === "") {
                Swal.showValidationMessage("Nama tidak boleh kosong");
              }

              return { jumlah, nama, partner };
            },
          }).then(async (swalResult) => {
            if (swalResult.isConfirmed) {
              const { jumlah, nama, partner } = swalResult.value;

              const res = await fetch("/invitation/simpan-kehadiran", {
                method: "POST",
                headers: {
                  "Content-Type": "application/x-www-form-urlencoded",
                },
                body: `id_invitation=${
                  data.id
                }&jumlah=${jumlah}&nama=${encodeURIComponent(
                  nama
                )}&partner=${encodeURIComponent(partner)}`,
              });

              const hasil = await res.json();

              if (hasil.status) {
                Swal.fire({
                  title: "Tersimpan!",
                  text: hasil.message || "Kehadiran berhasil dicatat.",
                  icon: "success",
                  showConfirmButton: false,
                  timer: 2500,
                  timerProgressBar: true,
                }).then(() => {
                  $("#tabel_daftar_hadir").DataTable().ajax.reload(null, false);
                  scanner.resume(); // lanjut scan
                });
              } else {
                Swal.fire(
                  "Gagal",
                  hasil.message || "Gagal menyimpan data.",
                  "error"
                ).then(() => scanner.resume());
              }
            } else {
              scanner.resume(); // batal, lanjut scan
            }
          });
        } else {
          Swal.fire("Tamu tidak ditemukan", result.message, "error").then(() =>
            scanner.resume()
          );
        }
      } catch (error) {
        console.error("❌ ERROR:", error);
        Swal.fire("Error", "Terjadi kesalahan saat membaca QR.", "error").then(
          () => scanner.resume()
        );
      }
    });
  } else {
    Swal.fire(
      "Kamera Tidak Tersedia",
      "Tidak ditemukan perangkat kamera.",
      "error"
    );
  }
});

